function pal() {
  if (style === 'baked') return { cH:16, cS:52, cB:52, sh:10, hi:[30,40,100], neg:0 };
  if (style === 'stone') return { cH:150, cS:12, cB:50, sh:150, hi:[130,20,100], neg:0 };
  if (style === 'lapis') return { cH:222, cS:62, cB:24, sh:224, hi:[196,60,100], neg:1 };
  return { cH:wh(P.hue+2), cS:38, cB:54, sh:26, hi:[38,45,100], neg:0 }; // clay
}
const C = pal();

// ---- ground: clay slab with mottle, ruled cases, raised bevel edge ----------
if (!S.clay || S.ckey !== key || S.cstyle !== style || S.cseed !== (P.seed|0)) {
  S.ckey = key; S.cstyle = style; S.cseed = (P.seed|0);
  const pg = createGraphics(BW, BH); pg.colorMode(HSB, 360, 100, 100, 100); pg.noStroke();
  pg.background(C.cH, C.cS, C.cB);
  pg.blendMode(C.neg ? ADD : MULTIPLY);
  for (let i = 0; i < 120; i++) {
    const mx = fr(i*3+1)*BW, my = fr(i*5+2)*BH, mr = BW*(0.08+fr(i*7+3)*0.30);
    pg.fill(C.cH, C.cS*0.7, C.neg? 30+fr(i)*20 : 100-(8+fr(i)*16), 9); pg.ellipse(mx, my, mr, mr*0.85);
  }
  pg.blendMode(BLEND);
  for (let i = 0; i < 3400; i++) { pg.fill(C.cH, C.cS, C.neg? C.cB+fr(i)*24 : C.cB-fr(i)*22, 5); pg.rect(fr(i*2.1+900)*BW, fr(i*3.7+901)*BH, 1.2, 1.2); }
  // raised beveled tablet edge
  const bez = BW*0.055;
  pg.noFill();
  for (let e = 0; e < bez; e++) {
    const f = e/bez;
    pg.strokeWeight(1.4);
    pg.stroke(C.cH, C.cS, C.cB*(0.6+0.4*f), 22*(1-f));   // dark inner
    pg.rect(e, e, BW-2*e, BH-2*e);
