  pg.noStroke();
  S.clay = pg;
  const vg = createGraphics(BW, BH); vg.colorMode(HSB, 360, 100, 100, 100); vg.clear();
  const gc = vg.drawingContext; const rg = gc.createRadialGradient(BW/2,BH/2,BH*0.2,BW/2,BH/2,BH*0.8);
  rg.addColorStop(0,'rgba(0,0,0,0)'); rg.addColorStop(0.6,'rgba(0,0,0,0.10)'); rg.addColorStop(1,'rgba(0,0,0,0.46)');
