  const mL=BW*0.09, mR=BW*0.91, mT=BH*0.09, mB=BH*0.91;
  const cw=(mR-mL)/nCols, chh=(mB-mT)/nRows;
  const cell = Math.min(cw, chh);
  const signs=[];
