    if (fr(gi*7+3) < 0.14) { gi++; continue; }  // word/blank spacing
    const cx = mL + (c+0.5)*cw, cy = mT + (r+0.5)*chh;
    const nW = 2 + Math.floor(fr(gi*3+1) * (2 + P.wedge*5));
    const wed=[];
    for (let w=0; w<nW; w++){
      const wr = fr(gi*11 + w*5 + 2);
      let a; const tp = fr(gi*13 + w*3 + 4);
      if (tp < 0.34) a = Math.PI*0.5;            // vertical
      else if (tp < 0.62) a = 0;                  // horizontal
      else if (tp < 0.82) a = Math.PI*(0.2+wr*0.2); // diagonal
      else a = Math.PI*(0.75+wr*0.15);            // Winkelhaken-ish
      const off = cell*0.30;
      wed.push({
        ox: (fr(gi*17+w*7+1)-0.5)*off, oy: (fr(gi*19+w*7+2)-0.5)*off,
        a, len: cell*(0.16+fr(gi*23+w*3+5)*0.16), hw: 0.34+fr(gi*29+w+6)*0.14
      });
    }
    signs.push({ cx, cy, cell, wed });
    gi++;
  }
  S.signs=signs; S.prog=0; S.phase='write'; S.dwell=0;
}

// ---- advance impress-front ---------------------------------------------------
const total=S.signs.length;
const spd=0.35 + P.speed*1.2;
if (S.phase==='write'){ S.prog += (spd*7)/(K.fps||60); if (S.prog>=total){ S.prog=total; S.phase='dwell'; S.dwell=0; } }
else if (S.phase==='dwell'){ S.dwell += 1/(K.fps||60); if (S.dwell > 3.0/(0.4+P.speed*0.8)) S.phase='fade'; S.fade=(S.fade==null?100:S.fade); }
else if (S.phase==='fade'){ S.fade=(S.fade==null?100:S.fade)-120/(K.fps||60); if (S.fade<=0){ S.tab=(S.tab||0)+1; S.signs=null; } }

// ---- render ------------------------------------------------------------------
const t=K.t;
const sxr=width/BW, syr=height/BH;
const dx = Math.sin(t*0.12)*width*0.005 + Math.sin(t*0.29+1.1)*width*0.004;
const dy = Math.cos(t*0.10)*height*0.005;
