const lang = 2.2 + Math.sin(t*0.14)*0.9 + Math.sin(t*0.33+1.0)*0.5;
const ldx=Math.cos(lang), ldy=Math.sin(lang);
const lpx = (Math.sin(t*0.19)*0.5+0.5)*0.6 + (Math.sin(t*0.052+2)*0.5+0.5)*0.4;

