const glowA=(10+P.energy*12+A.rms*8)*(C.neg?0.7:1);
for (let b=0;b<4;b++){ fill(C.hi[0], C.hi[1]*0.6, C.hi[2], glowA*(1-b/4)*0.4); ellipse(lpx*width, height*(0.4+Math.sin(t*0.21)*0.12), width*(0.5-b*0.06), height*(0.7-b*0.08)); }
