// impressed wedges
const drawn = Math.min(total, Math.floor(S.prog));
const depth = 0.4 + P.energy*0.9;
const shB = C.neg ? C.cB+6 : C.cB*0.42;         // depression shadow brightness
const rim = 0.5 + P.energy*0.5;
function wedge(cx, cy, w, scl, aFade){
  const a=w.a, len=w.len*scl*(0.7+P.scale*0.6), hw=len*w.hw;
  const dxu=Math.cos(a), dyu=Math.sin(a), px=-Math.sin(a), py=Math.cos(a);
  const bx=cx - dxu*len*0.5, by=cy - dyu*len*0.5;   // back center
  const tx=cx + dxu*len*0.5, ty=cy + dyu*len*0.5;   // tip
