  // depression fill
  noStroke(); fill(C.sh, C.cS*0.8, shB, 78*aFade);
  triangle(blx*sxr,bly*syr, brx*sxr,bry*syr, tx*sxr,ty*syr);
  // per-edge rim lit by raking light
  const edges=[[blx,bly,brx,bry],[brx,bry,tx,ty],[tx,ty,blx,bly]];
