    if (d>0){ strokeWeight(Math.max(0.7,len*0.09*sxr)); stroke(C.hi[0],C.hi[1]*0.5,C.hi[2], (30+70*d)*rim*aFade); }
    else   { strokeWeight(Math.max(0.5,len*0.06*sxr)); stroke(C.sh,C.cS,shB*0.7, 40*(-d)*aFade); }
